namespace UI_Desktop.Auth;

internal static class LoginWebViewHtmlBuilder
{
	public static string BuildDocument(bool rememberSessionByDefault)
	{
		string text = (rememberSessionByDefault ? " checked" : string.Empty);
		return "<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n    <meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\r\n    <title>Đăng nhập NestG</title>\r\n    <style>\r\n        :root {\r\n            color-scheme: dark;\r\n            --bg: #070d14;\r\n            --panel: #101a26;\r\n            --panel-2: #0c151f;\r\n            --line: #203044;\r\n            --text: #f2f7ff;\r\n            --muted: #8fa0b6;\r\n            --soft: #c5d1df;\r\n            --cyan: #27d9ff;\r\n            --blue: #289bed;\r\n            --green: #9bd33d;\r\n        }\r\n\r\n        * { box-sizing: border-box; }\r\n        html, body { width: 100%; height: 100%; min-height: 0; margin: 0; }\n        body {\n            min-width: 0;\n            overflow: hidden;\n            background:\r\n                radial-gradient(circle at 25% 34%, rgba(39, 153, 220, .18), transparent 28%),\r\n                radial-gradient(circle at 70% 108%, rgba(80, 153, 44, .12), transparent 30%),\r\n                linear-gradient(145deg, #0b131e 0%, #060b11 72%);\r\n            color: var(--text);\r\n            font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\r\n        }\r\n\r\n        button, input { font: inherit; }\r\n        button { color: inherit; }\r\n        [hidden] { display: none !important; }\r\n\r\n        .app-shell {\n            height: 100vh;\n            min-height: 100vh;\n            display: grid;\n            grid-template-rows: 46px minmax(0, 1fr);\r\n        }\r\n\r\n        .titlebar {\r\n            position: relative;\r\n            z-index: 10;\r\n            display: grid;\r\n            grid-template-columns: minmax(0, 1fr) auto;\r\n            align-items: center;\r\n            border-bottom: 1px solid rgba(75, 95, 120, .24);\r\n            background: rgba(8, 12, 18, .94);\r\n            box-shadow: 0 12px 32px rgba(0, 0, 0, .24);\r\n        }\r\n\r\n        .brand {\r\n            height: 100%;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            min-width: 0;\r\n            padding-left: 16px;\r\n            color: #dbe8f5;\r\n            font-size: 12px;\r\n            font-weight: 850;\r\n            letter-spacing: .08em;\r\n            user-select: none;\r\n        }\r\n\r\n        .brand img {\r\n            width: 27px;\r\n            height: 27px;\r\n            object-fit: contain;\r\n            filter: drop-shadow(0 2px 5px rgba(0, 0, 0, .45));\r\n        }\r\n\r\n        .drag-region {\r\n            position: absolute;\r\n            inset: 0 116px 0 0;\r\n        }\r\n\r\n        .window-controls {\r\n            position: relative;\r\n            z-index: 2;\r\n            height: 100%;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 4px;\r\n            padding-right: 8px;\r\n        }\r\n\r\n        .window-button {\r\n            width: 32px;\r\n            height: 28px;\r\n            display: grid;\r\n            place-items: center;\r\n            border: 0;\r\n            border-radius: 4px;\r\n            background: transparent;\r\n            color: #cfd9e6;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n        }\r\n\r\n        .window-button:hover { background: rgba(255, 255, 255, .08); }\r\n        .window-button.is-close:hover { background: #c83232; color: #fff; }\r\n\r\n        .auth-stage {\r\n            min-height: 0;\r\n            display: grid;\r\n            grid-template-columns: minmax(300px, .92fr) minmax(410px, 1.08fr);\r\n            align-items: stretch;\r\n            padding: clamp(22px, 4vw, 58px);\r\n        }\r\n\r\n        .visual-panel {\r\n            position: relative;\r\n            min-height: 500px;\r\n            overflow: hidden;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: flex-end;\r\n            padding: clamp(34px, 5vw, 72px);\r\n            border: 1px solid rgba(71, 125, 163, .26);\r\n            border-right: 0;\r\n            border-radius: 6px 0 0 6px;\r\n            background:\r\n                linear-gradient(180deg, rgba(4, 13, 21, .08), rgba(3, 10, 16, .88)),\r\n                linear-gradient(135deg, rgba(35, 126, 184, .28), rgba(8, 23, 35, .3) 56%, rgba(112, 161, 45, .12));\r\n            box-shadow: 0 26px 70px rgba(0, 0, 0, .32);\r\n        }\r\n\r\n        .visual-panel::before {\r\n            content: \"\";\r\n            position: absolute;\r\n            width: 440px;\r\n            height: 440px;\r\n            left: 50%;\r\n            top: 42%;\r\n            border: 1px solid rgba(102, 192, 244, .11);\r\n            transform: translate(-50%, -50%) rotate(45deg);\r\n            box-shadow:\r\n                0 0 0 62px rgba(102, 192, 244, .025),\r\n                0 0 0 124px rgba(102, 192, 244, .018);\r\n        }\r\n\r\n        .visual-logo {\r\n            position: absolute;\r\n            left: 50%;\r\n            top: 43%;\r\n            width: min(230px, 48%);\r\n            aspect-ratio: 1;\r\n            object-fit: contain;\r\n            opacity: .88;\r\n            transform: translate(-50%, -50%);\r\n            filter: drop-shadow(0 20px 35px rgba(0, 0, 0, .52));\r\n        }\r\n\r\n        .visual-copy {\r\n            position: relative;\r\n            z-index: 2;\r\n        }\r\n\r\n        .visual-copy span {\r\n            color: var(--cyan);\r\n            font-size: 11px;\r\n            font-weight: 900;\r\n            letter-spacing: .16em;\r\n        }\r\n\r\n        .visual-copy h1 {\r\n            max-width: 420px;\r\n            margin: 10px 0 0;\r\n            color: #f5f9fd;\r\n            font-size: clamp(26px, 3vw, 42px);\r\n            line-height: 1.08;\r\n            letter-spacing: -.03em;\r\n        }\r\n\r\n        .login-panel {\r\n            min-height: 500px;\r\n            display: grid;\r\n            place-items: center;\r\n            padding: clamp(30px, 5vw, 76px);\r\n            border: 1px solid rgba(71, 125, 163, .26);\r\n            border-radius: 0 6px 6px 0;\r\n            background:\r\n                linear-gradient(180deg, rgba(16, 31, 44, .98), rgba(8, 20, 30, .99));\r\n            box-shadow: 0 26px 70px rgba(0, 0, 0, .32);\r\n        }\r\n\r\n        .login-card {\r\n            width: min(420px, 100%);\r\n        }\r\n\r\n        .eyebrow {\r\n            color: #66c0f4;\r\n            font-size: 10px;\r\n            font-weight: 900;\r\n            letter-spacing: .15em;\r\n        }\r\n\r\n        .login-card h2 {\r\n            margin: 8px 0 5px;\r\n            color: #f4f8fc;\r\n            font-size: clamp(29px, 3vw, 39px);\r\n            line-height: 1.15;\r\n            letter-spacing: -.03em;\r\n        }\r\n\r\n        .subtitle {\r\n            margin: 0 0 28px;\r\n            color: var(--muted);\r\n            font-size: 13px;\r\n        }\r\n\r\n        .field {\r\n            display: grid;\r\n            gap: 8px;\r\n            margin-top: 18px;\r\n        }\r\n\r\n        .field label {\r\n            color: #aabcc9;\r\n            font-size: 11px;\r\n            font-weight: 800;\r\n            letter-spacing: .04em;\r\n            text-transform: uppercase;\r\n        }\r\n\r\n        .input-shell {\r\n            position: relative;\r\n        }\r\n\r\n        .input-shell input {\r\n            width: 100%;\r\n            height: 50px;\r\n            border: 1px solid rgba(86, 128, 160, .42);\r\n            border-radius: 4px;\r\n            outline: 0;\r\n            background: rgba(5, 17, 25, .82);\r\n            color: #eef6fc;\r\n            padding: 0 15px;\r\n            caret-color: var(--cyan);\r\n            transition: border-color .16s ease, background .16s ease, box-shadow .16s ease;\r\n        }\r\n\r\n        .input-shell input::placeholder { color: #62798a; }\r\n        .input-shell input:focus {\r\n            border-color: rgba(102, 192, 244, .82);\r\n            background: rgba(7, 22, 32, .98);\r\n            box-shadow: 0 0 0 3px rgba(102, 192, 244, .09);\r\n        }\r\n\r\n        .input-shell.has-action input { padding-right: 82px; }\r\n\r\n        .password-toggle {\r\n            position: absolute;\r\n            top: 50%;\r\n            right: 10px;\r\n            width: 58px;\r\n            height: 30px;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            border: 1px solid rgba(102, 192, 244, .18);\r\n            border-radius: 999px;\r\n            background: rgba(102, 192, 244, .07);\r\n            color: #9fdfff;\r\n            cursor: pointer;\r\n            font-size: 11px;\r\n            font-weight: 850;\r\n            letter-spacing: .02em;\r\n            transform: translateY(-50%);\r\n            transition: border-color .16s ease, background .16s ease, color .16s ease, box-shadow .16s ease;\r\n        }\r\n\r\n        .password-toggle:hover,\r\n        .password-toggle:focus-visible {\r\n            border-color: rgba(102, 192, 244, .48);\r\n            background: rgba(102, 192, 244, .14);\r\n            color: #dcf6ff;\r\n            box-shadow: 0 0 0 3px rgba(102, 192, 244, .08);\r\n            outline: 0;\r\n        }\r\n\r\n        .form-options {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            gap: 18px;\r\n            margin-top: 18px;\r\n            color: #9eb0bf;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .remember {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            cursor: pointer;\r\n            user-select: none;\r\n        }\r\n\r\n        .remember input {\r\n            width: 16px;\r\n            height: 16px;\r\n            margin: 0;\r\n            accent-color: var(--blue);\r\n        }\r\n\r\n        .link-button {\r\n            padding: 0;\r\n            border: 0;\r\n            background: transparent;\r\n            color: #8fd4ff;\r\n            cursor: pointer;\r\n            font-size: 12px;\r\n            font-weight: 750;\r\n        }\r\n\r\n        .link-button:hover,\r\n        .link-button:focus-visible {\r\n            color: #c4efff;\r\n            text-decoration: underline;\r\n            outline: 0;\r\n        }\r\n\r\n        .link-button:disabled {\r\n            cursor: wait;\r\n            opacity: .55;\r\n            text-decoration: none;\r\n        }\r\n\r\n        .status {\r\n            min-height: 20px;\r\n            margin: 15px 0 0;\r\n            color: #91c8e8;\r\n            font-size: 12px;\r\n            line-height: 1.45;\r\n        }\r\n\r\n        .status.is-error { color: #ff9d9d; }\r\n\r\n        .submit-button {\r\n            width: 100%;\r\n            min-height: 50px;\r\n            margin-top: 9px;\r\n            border: 1px solid rgba(190, 240, 111, .24);\r\n            border-radius: 4px;\r\n            background: linear-gradient(180deg, #9bd33d 0%, #75a920 100%);\r\n            color: #fff;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n            font-weight: 900;\r\n            box-shadow:\r\n                inset 0 1px 0 rgba(255, 255, 255, .14),\r\n                0 10px 24px rgba(89, 132, 28, .18);\r\n            transition: filter .16s ease, transform .16s ease, opacity .16s ease;\r\n        }\r\n\r\n        .submit-button:hover,\r\n        .submit-button:focus-visible {\r\n            filter: brightness(1.08);\r\n            transform: translateY(-1px);\r\n            outline: 0;\r\n        }\r\n\r\n        .submit-button:disabled {\r\n            cursor: wait;\r\n            opacity: .68;\r\n            transform: none;\r\n        }\r\n\r\n        .register-row {\r\n            margin: 23px 0 0;\r\n            color: #7f93a4;\r\n            text-align: center;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .register-row .link-button { margin-left: 5px; }\r\n\r\n        @media (max-width: 920px) {\r\n            .auth-stage {\r\n                grid-template-columns: 1fr;\r\n                padding: 24px;\r\n            }\r\n\r\n            .visual-panel { display: none; }\r\n            .login-panel {\r\n                min-height: calc(100vh - 94px);\r\n                border-radius: 6px;\r\n            }\r\n        }\r\n\r\n        @media (max-height: 690px) {\n            body { overflow: hidden; }\n            .app-shell { grid-template-rows: 40px minmax(0, 1fr); }\n            .auth-stage { padding: 12px clamp(14px, 3vw, 26px); }\n            .visual-panel, .login-panel { min-height: 0; }\n            .login-panel { padding: 16px clamp(22px, 5vw, 46px); }\n            .login-card h2 { margin-block: 5px 3px; font-size: 30px; }\n            .subtitle { margin-bottom: 12px; }\n            .field { gap: 5px; margin-top: 10px; }\n            .input-shell input { height: 42px; }\n            .form-options { margin-top: 10px; }\n            .status { min-height: 16px; margin-top: 7px; }\n            .submit-button { min-height: 40px; margin-top: 5px; }\n            .register-row { margin-top: 9px; }\n        }\n\n        @media (max-height: 480px) {\n            .app-shell { grid-template-rows: 34px minmax(0, 1fr); }\n            .brand { padding-left: 10px; font-size: 10px; }\n            .brand img { width: 22px; height: 22px; }\n            .window-controls { padding-right: 4px; }\n            .window-button { height: 26px; }\n            .auth-stage { padding: 4px 8px; }\n            .login-panel { padding: 6px 16px; }\n            .eyebrow { font-size: 9px; }\n            .login-card h2 { margin: 2px 0; font-size: 26px; line-height: 1.1; }\n            .subtitle { margin-bottom: 5px; font-size: 11px; }\n            .field { gap: 3px; margin-top: 5px; }\n            .field label { font-size: 9px; }\n            .input-shell input { height: 34px; padding-inline: 11px; font-size: 12px; }\n            .input-shell.has-action input { padding-right: 70px; }\n            .password-toggle { right: 6px; width: 52px; height: 26px; font-size: 10px; }\n            .form-options { margin-top: 5px; font-size: 10px; }\n            .remember input { width: 14px; height: 14px; }\n            .link-button { font-size: 10px; }\n            .status { min-height: 14px; margin-top: 3px; font-size: 10px; line-height: 1.25; }\n            .submit-button { min-height: 34px; margin-top: 3px; font-size: 11px; }\n            .register-row { margin-top: 4px; font-size: 10px; }\n        }\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"app-shell\">\r\n        <header class=\"titlebar\">\r\n            <div class=\"drag-region\" data-drag-region></div>\r\n            <div class=\"brand\">\r\n                <img src=\"https://nestg-assets.local/logo.png\" alt=\"\" />\r\n                <span>NESTG LAUNCHER</span>\r\n            </div>\r\n            <div class=\"window-controls\">\r\n                <button type=\"button\" class=\"window-button\" data-action=\"minimize\" aria-label=\"Thu nhỏ\">−</button>\r\n                <button type=\"button\" class=\"window-button\" data-action=\"maximize\" aria-label=\"Phóng to\">□</button>\r\n                <button type=\"button\" class=\"window-button is-close\" data-action=\"close\" aria-label=\"Đóng\">×</button>\r\n            </div>\r\n        </header>\r\n\r\n        <main class=\"auth-stage\">\r\n            <section class=\"visual-panel\" aria-hidden=\"true\">\r\n                <img class=\"visual-logo\" src=\"https://nestg-assets.local/logo.png\" alt=\"\" />\r\n                <div class=\"visual-copy\">\r\n                    <span>NESTG STORE</span>\r\n                    <h1>Thư viện game của bạn.</h1>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"login-panel\">\r\n                <form class=\"login-card\" data-login-form novalidate>\r\n                    <span class=\"eyebrow\">TÀI KHOẢN NESTG</span>\r\n                    <h2>Đăng nhập</h2>\r\n                    <p class=\"subtitle\">Tiếp tục vào launcher.</p>\r\n\r\n                    <div class=\"field\">\r\n                        <label for=\"email\">Email</label>\r\n                        <div class=\"input-shell\">\r\n                            <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"username\" placeholder=\"you@example.com\" required />\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"field\">\r\n                        <label for=\"password\">Mật khẩu</label>\r\n                        <div class=\"input-shell has-action\">\r\n                            <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Nhập mật khẩu\" required />\r\n                            <button type=\"button\" class=\"password-toggle\" data-password-toggle>Hiện</button>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"form-options\">\r\n                        <label class=\"remember\">\r\n                            <input name=\"remember\" type=\"checkbox\"" + text + " />\r\n                            <span>Ghi nhớ</span>\r\n                        </label>\r\n                        <button type=\"button\" class=\"link-button\" data-action=\"forgotPassword\">Quên mật khẩu?</button>\r\n                    </div>\r\n\r\n                    <p class=\"status\" data-status aria-live=\"polite\"></p>\r\n                    <button type=\"submit\" class=\"submit-button\" data-submit>Đăng nhập</button>\r\n\r\n                    <p class=\"register-row\">\r\n                        Chưa có tài khoản?\r\n                        <button type=\"button\" class=\"link-button\" data-action=\"register\">Tạo tài khoản</button>\r\n                    </p>\r\n                </form>\r\n            </section>\r\n        </main>\r\n    </div>\r\n\r\n    <script>\r\n        (() => {\r\n            const post = message => window.chrome?.webview?.postMessage(message);\r\n            const form = document.querySelector('[data-login-form]');\r\n            const emailInput = form?.elements.namedItem('email');\r\n            const passwordInput = form?.elements.namedItem('password');\r\n            const rememberInput = form?.elements.namedItem('remember');\r\n            const submitButton = document.querySelector('[data-submit]');\r\n            const status = document.querySelector('[data-status]');\r\n            const passwordToggle = document.querySelector('[data-password-toggle]');\r\n            const secondaryActions = document.querySelectorAll(\r\n                '[data-action=\"forgotPassword\"], [data-action=\"register\"]');\r\n\r\n            function setState(isBusy, message = '', isError = false) {\r\n                if (submitButton) {\r\n                    submitButton.disabled = isBusy;\r\n                    submitButton.textContent = isBusy ? 'Đang đăng nhập...' : 'Đăng nhập';\r\n                }\r\n\r\n                if (emailInput) emailInput.disabled = isBusy;\r\n                if (passwordInput) passwordInput.disabled = isBusy;\r\n                if (rememberInput) rememberInput.disabled = isBusy;\r\n                secondaryActions.forEach(button => button.disabled = isBusy);\r\n\r\n                if (status) {\r\n                    status.textContent = message;\r\n                    status.classList.toggle('is-error', Boolean(isError));\r\n                }\r\n            }\r\n\r\n            window.__nestgLogin = {\r\n                setState,\r\n                focus() {\r\n                    emailInput?.focus();\r\n                }\r\n            };\r\n\r\n            form?.addEventListener('submit', event => {\r\n                event.preventDefault();\r\n\r\n                const email = String(emailInput?.value || '').trim();\r\n                const password = String(passwordInput?.value || '');\r\n                if (!email || !password) {\r\n                    setState(false, 'Vui lòng nhập email và mật khẩu.', true);\r\n                    (!email ? emailInput : passwordInput)?.focus();\r\n                    return;\r\n                }\r\n\r\n                setState(true);\r\n                post({\r\n                    type: 'login',\r\n                    email,\r\n                    password,\r\n                    remember: Boolean(rememberInput?.checked)\r\n                });\r\n            });\r\n\r\n            passwordToggle?.addEventListener('click', () => {\r\n                if (!passwordInput) return;\r\n                const showPassword = passwordInput.type === 'password';\r\n                passwordInput.type = showPassword ? 'text' : 'password';\r\n                passwordToggle.textContent = showPassword ? 'Ẩn' : 'Hiện';\r\n                passwordInput.focus();\r\n            });\r\n\r\n            document.addEventListener('pointerdown', event => {\r\n                const target = event.target instanceof Element ? event.target : null;\r\n                if (target?.closest('[data-drag-region]')) {\r\n                    post({ type: 'dragWindow' });\r\n                }\r\n            });\r\n\r\n            document.addEventListener('click', event => {\r\n                const target = event.target instanceof Element ? event.target.closest('[data-action]') : null;\r\n                if (!target) return;\r\n                post({ type: target.getAttribute('data-action') });\r\n            });\r\n\r\n            window.requestAnimationFrame(() => emailInput?.focus());\r\n        })();\r\n    </script>\r\n</body>\r\n</html>";
	}
}
